    ArticPatch vowel_patch (size_t index, BodyMix body)
    {
        const auto& v = VOWELS[index < N_VOWELS ? index : 13];
        std::pair<double, ArticPatch> parts[3] = {
            { 0, v.male }, { 0, v.female }, { 0, v.child }
        };
        double w[3]; body.weights (w);
        parts[0].first = w[0]; parts[1].first = w[1]; parts[2].first = w[2];
        return ArticPatch::blend (parts, 3);
    }

    size_t nearest_vowel (double height, double back)
    {
        size_t best = 13; // schwa
        auto dmin = 1e9;
        for (size_t i = 0; i < N_VOWELS; ++i)
        {
            const auto dh = VOWELS[i].height - height, db = VOWELS[i].back - back;
            const auto d = dh * dh + db * db;
            if (d < dmin) { dmin = d; best = i; }
        }
        return best;
    }

    ArticPatch vowel_at (double height, double back, BodyMix body)
    {
        // inverse-distance blend of the three nearest vowels
        struct N { size_t i; double d; };
        N n[N_VOWELS];
        for (size_t i = 0; i < N_VOWELS; ++i)
        {
            const auto dh = VOWELS[i].height - height, db = VOWELS[i].back - back;
            n[i] = { i, std::sqrt (dh * dh + db * db) };
        }
        for (size_t a = 0; a < 3; ++a)
            for (size_t b = a + 1; b < N_VOWELS; ++b)
                if (n[b].d < n[a].d) std::swap (n[a], n[b]);
        if (n[0].d < 1e-6) return vowel_patch (n[0].i, body);
        std::pair<double, ArticPatch> parts[3];
        int used = 0;
        for (int k = 0; k < 3; ++k)
        {
            const auto w = 1.0 / js_max (1e-6, n[size_t (k)].d);
            parts[used++] = { w, vowel_patch (n[size_t (k)].i, body) };
        }
        return ArticPatch::blend (parts, size_t (used));
    }
